const raw = $input.first().json;
// A webhook delivers { body, headers, query }; a manual execution or a Chat
// trigger delivers the fields directly. Accept both so the same workflow can be
// driven from curl, from the n8n UI, or from a Teams/Power Automate POST.
const body = raw.body ?? raw;

const text = String(body.text ?? body.chatInput ?? '').trim();
const readings = body.readings && typeof body.readings === 'object' ? body.readings : {};

if (!text) {
  throw new Error('No signal text supplied. POST { "text": "what was reported" }.');
}

return [{
  json: {
    config: CONFIG,
    signal: {
      runId: 'RUN-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 8),
      receivedAt: new Date().toISOString(),
      text,
      originalText: text,
      kind: body.kind ?? 'operator_request',
      channel: body.channel ?? 'n8n',
      reportedBy: body.reported_by ?? body.reportedBy ?? null,
      assetHint: body.asset_hint ?? body.assetHint ?? null,
      readings,
    },
  },
}];

// Input guardrail + PII redaction.
//
// Runs BEFORE anything reaches a model. The order matters: screen first so a
// prompt-injection payload never reaches the LLM at all, then redact so personal
// data never leaves the trust boundary. A maintenance report can arrive from an
// email or a Teams message, so the text is genuinely untrusted input.

const signal = $input.first().json.signal;

const INJECTION = [
  /ignore (?:all |any )?(?:previous|prior|above) instructions/i,
  /disregard (?:the )?(?:system|previous) (?:prompt|instructions)/i,
  /you are now (?:a|an|in) /i,
  /reveal (?:your )?(?:system )?prompt/i,
  /\bauto[- ]?approve\b.*\beverything\b/i,
  /<\/?(?:system|instructions?)>/i,
];

const PII = [
  ['Email', /\b[\w.+-]+@[\w-]+\.[\w.]{2,}\b/g],
  ['PhoneNumber', /(?:\+\d{1,3}[\s-]?)?(?:\(?\d{2,4}\)?[\s-]?)\d{3}[\s-]?\d{3,4}\b/g],
  ['EmployeeId', /\b(?:emp|employee|badge|pers)[\s#:-]*\d{3,8}\b/gi],
];

const matched = INJECTION.filter((re) => re.test(signal.text));

let redacted = signal.text;
let redactions = 0;
const categories = [];
for (const [label, re] of PII) {
  const before = redacted;
  redacted = redacted.replace(re, `[${label}]`);
  if (redacted !== before) {
    // Count how many placeholders this pattern introduced.
    const n = (redacted.match(new RegExp(`\\[${label}\\]`, 'g')) || []).length;
    redactions += n;
    categories.push(label);
  }
}

return [{
  json: {
    signal: { ...signal, text: redacted, redactions, piiCategories: categories },
    guard: {
      safe: matched.length === 0,
      reason: matched.length ? 'prompt_injection' : null,
      redactions,
      categories,
    },
  },
}];

// Asset resolution + manual retrieval.
//
// Resolution is layered cheapest-first: explicit id, then a configured alias,
// then "only one machine of that class exists", then fuzzy token overlap. Most
// real signals name the asset plainly and paying a model to read "PMP-003" back
// to you is how a demo becomes expensive in production.
//
// Retrieval is a small TF-IDF-ish score over manual sections, filtered to the
// asset's class first -- returning the crane manual for a compressor fault is
// worse than returning nothing. Chunks are whole manual sections, because the
// section id IS the citation an engineer needs.

const cfg = $('Load config').first().json.config;
const { signal, guard } = $input.first().json;

const STOP = new Set(['the','a','an','is','are','was','on','in','at','of','and','to','it','its','there','has','have','with','from','for','be','been']);
const tokens = (s) => String(s).toLowerCase().match(/[a-z0-9]+/g)?.filter((t) => !STOP.has(t)) ?? [];

const NUMBER_WORDS = { one:'1', two:'2', three:'3', four:'4', five:'5', six:'6', seven:'7', eight:'8', nine:'9', ten:'10', fourteen:'14' };

// Operator vocabulary vs manual vocabulary. A fitter says "leaking oil"; the
// manual says "shaft seal". Bridging that gap is most of what makes retrieval
// work on real maintenance text.
const SYNONYMS = {
  leak:['leakage','weeping','drip','seal'], leaking:['leakage','seal','weeping','drip'],
  noise:['noisy','knocking','rattling','grinding'], grinding:['noise','brake','wear'],
  hot:['temperature','overheating'], overheating:['temperature','hot','cooler'],
  vibration:['vibrating','juddering','bearing','rms'], smoke:['exhaust','combustion','black'],
  drift:['drifts','brake','holding'], drifts:['drift','brake','holding'],
  rope:['wire','discard','broken'], pressure:['loss','hydraulic'],
  belt:['tracking','conveyor','torn'], start:['starting','crank'],
};
const expand = (ts) => ts.flatMap((t) => [t, ...(SYNONYMS[t] ?? [])]);

// ---------------------------------------------------------------- resolution

const haystack = `${signal.assetHint ?? ''} ${signal.text}`;
// Telemetry is deliberately NOT part of the matching text: "8.2" tokenises to
// {8, 2} and the "2" then matches "Gantry Crane 2", so a conveyor alert
// resolves to a crane.
const signalTokens = new Set(tokens(haystack));
for (const [word, digit] of Object.entries(NUMBER_WORDS)) {
  if (new RegExp(`\\b${word}\\b`, 'i').test(haystack)) signalTokens.add(digit);
}

const scoreAsset = (asset) => {
  const upper = haystack.toUpperCase();
  if (upper.includes(asset.id) || upper.replace(/[-\s]/g, '').includes(asset.id.replace('-', ''))) return 1.0;
  for (const alias of asset.aliases ?? []) {
    if (haystack.toLowerCase().includes(alias.toLowerCase())) return 0.93;
  }
  const assetTokens = new Set([...tokens(`${asset.name} ${asset.class} ${asset.site}`), asset.id.split('-')[1].replace(/^0+/, '')]);
  const overlap = [...signalTokens].filter((t) => assetTokens.has(t));
  if (!overlap.length) return 0;
  let score = overlap.length / assetTokens.size;
  const unit = asset.id.split('-')[1].replace(/^0+/, '');
  if (unit && signalTokens.has(unit)) score += 0.35;
  return Math.min(Number(score.toFixed(3)), 0.9);
};

let ranked = cfg.assets.map((a) => ({ asset: a, score: scoreAsset(a) }))
  .sort((x, y) => y.score - x.score);

let asset = null;
let confidence = ranked[0]?.score ?? 0;

if (confidence >= 0.25 && (confidence - (ranked[1]?.score ?? 0) >= 0.08 || confidence >= 0.9)) {
  asset = ranked[0].asset;
} else {
  // "The generator will not start" is unambiguous on a site with one generator
  // and genuinely ambiguous on a site with six. Let the registry decide which
  // situation we are in rather than hard-coding either answer.
  const byClass = cfg.assets.filter((a) => a.class.split('_').some((w) => signalTokens.has(w)));
  if (byClass.length === 1) {
    asset = byClass[0];
    confidence = 0.78;
  } else {
    // Nothing matched clearly and the class is ambiguous. Below the floor it is
    // a guess, and guessing is worse than saying we do not know: rule AIQ-002
    // routes the unknown case to a person.
    confidence = Math.min(confidence, cfg.policy.assetConfidenceFloor - 0.01);
    asset = null;
  }
}

// ---------------------------------------------------------------- retrieval

const queryTerms = expand(tokens(signal.text));
const pool = cfg.manuals.filter((m) => !asset || m.classes.includes(asset.class));

const scored = pool.map((m) => {
  const docTokens = tokens(`${m.heading} ${m.text}`);
  const counts = docTokens.reduce((acc, t) => (acc[t] = (acc[t] ?? 0) + 1, acc), {});
  let score = 0;
  for (const term of queryTerms) {
    if (counts[term]) score += counts[term] / Math.sqrt(docTokens.length);
  }
  return { m, score };
}).filter((x) => x.score > 0).sort((x, y) => y.score - x.score).slice(0, 4);

const best = scored[0]?.score || 1;
const citations = scored.map(({ m, score }) => ({
  docId: m.docId,
  section: m.section,
  heading: m.heading,
  text: m.text,
  score: Number(Math.min(score / best, 1).toFixed(3)),
}));

return [{
  json: {
    signal,
    guard,
    asset,
    assetConfidence: Number(confidence.toFixed(3)),
    assetCandidates: ranked.slice(0, 3).filter((r) => r.score > 0.05).map((r) => ({ id: r.asset.id, name: r.asset.name, score: r.score })),
    citations,
    // Built here rather than inside the HTTP node's expression so the prompt is
    // readable, diffable and testable. House style: a narrow role, the grounding
    // material quoted verbatim with its section ids, an explicit instruction to
    // cite, a closed output schema, and a stated escape hatch -- most
    // hallucination is a prompt refusing to accept "I don't know" as an answer.
    llmPrompt: {
      system: [
        'You are a maintenance engineer\'s diagnostic assistant for industrial assets.',
        'You reason ONLY from the manual extracts provided. Every failure mode you',
        'propose must cite the section it came from, using the exact section id shown.',
        'If the extracts do not support a diagnosis, return an empty failure_modes',
        'list and a confidence below 0.4 rather than speculating.',
        '',
        'Severity definitions (use exactly these):',
        '  critical - asset must stop now; safety or total loss of function',
        '  high     - significant loss of function or a protective device impaired',
        '  medium   - degraded but serviceable; plan into the next window',
        '  low      - cosmetic or early-stage; monitor and trend',
        '',
        'Set safety_risk true only if the extracts indicate danger to people.',
        'Set environmental_risk true only for a release of oil, fuel or chemicals.',
      ].join('\n'),
      user: [
        `ASSET: ${asset ? `${asset.name} (${asset.class}, criticality ${asset.criticality} of 5)` : 'Unidentified'}`,
        '',
        'MANUAL EXTRACTS:',
        citations.map((c) => `[${c.docId} ${c.section} ${c.heading}]\n${c.text}`).join('\n\n') || '(none retrieved)',
        '',
        `REPORTED SIGNAL (${signal.kind}):`,
        `"${signal.text}"`,
        Object.keys(signal.readings ?? {}).length ? `TELEMETRY: ${JSON.stringify(signal.readings)}` : '',
        '',
        'Reply with JSON only:',
        '{"summary":"<two sentences for a supervisor>",',
        ' "failure_modes":[{"name":"<short name>","likelihood":<0.0-1.0>,"rationale":"<why>","sections":["<section id e.g. s3.1>"]}],',
        ' "severity":"critical|high|medium|low","safety_risk":true|false,"environmental_risk":true|false,',
        ' "injury_reported":true|false,"near_miss":true|false,"confidence":<0.0-1.0>,"recommended_spare":"<sku or null>"}',
      ].join('\n'),
    },
  },
}];

// Parse the Azure OpenAI reply into the same shape the built-in branch emits.
//
// Two jobs, both about not trusting the model's output shape:
//  1. Extract and validate JSON. A model occasionally wraps it in prose or a
//     fenced block, and a free-text answer cannot drive a work order.
//  2. Map the section ids it cited back to sections we actually retrieved.
//     A model can only legitimately cite what it was given; anything else is
//     dropped rather than displayed. That is the difference between a citation
//     and a plausible-looking string.
//
// If the reply cannot be salvaged we fall back to the retrieved evidence rather
// than failing the run -- but we say so in `source`, so nobody mistakes a
// degraded run for a good one.

const upstream = $('Resolve asset & retrieve manuals').first().json;
const { signal, guard, asset, assetConfidence, assetCandidates, citations } = upstream;

const raw = $input.first().json;
let content = raw?.choices?.[0]?.message?.content ?? '';

let data = null;
try {
  const cleaned = String(content).trim().replace(/^```(?:json)?\s*|\s*```$/g, '');
  data = JSON.parse(cleaned);
} catch (e) {
  const match = String(content).match(/\{[\s\S]*\}/);
  if (match) { try { data = JSON.parse(match[0]); } catch (_) { data = null; } }
}

const RANK = { low: 0, medium: 1, high: 2, critical: 3 };
const valid = data && typeof data.summary === 'string' && data.summary.trim() && RANK[String(data.severity).toLowerCase()] !== undefined;

if (!valid) {
  return [{
    json: {
      signal, guard, asset, assetConfidence, assetCandidates, citations,
      diagnosis: {
        summary: citations.length
          ? `Model reply could not be parsed. Closest manual section: ${citations[0].heading}.`
          : 'Model reply could not be parsed and no manual section matched.',
        severity: 'medium',
        safetyRisk: false, environmentalRisk: false, injury: false, nearMiss: false,
        // Deliberately below the confidence floor so rule AIQ-001 forces a human.
        confidence: 0.3,
        recommendedSpare: null,
        failureModes: [],
        source: 'azure openai (unparseable reply, degraded)',
        evidence: {},
      },
    },
  }];
}

const bySection = Object.fromEntries(citations.map((c) => [c.section.toLowerCase(), c]));
const failureModes = (Array.isArray(data.failure_modes) ? data.failure_modes : []).map((m) => {
  const cited = (Array.isArray(m.sections) ? m.sections : [])
    .map((s) => bySection[String(s).trim().toLowerCase().split(' ')[0]])
    .filter(Boolean);
  return {
    name: String(m.name ?? 'unnamed'),
    likelihood: Number(m.likelihood ?? 0),
    rationale: String(m.rationale ?? ''),
    citation: cited.length ? `${cited[0].docId} ${cited[0].section}` : null,
  };
}).filter((m) => m.citation);  // an uncited failure mode is not shown

return [{
  json: {
    signal, guard, asset, assetConfidence, assetCandidates, citations,
    diagnosis: {
      summary: String(data.summary).trim(),
      severity: String(data.severity).toLowerCase(),
      safetyRisk: Boolean(data.safety_risk),
      environmentalRisk: Boolean(data.environmental_risk),
      injury: Boolean(data.injury_reported),
      nearMiss: Boolean(data.near_miss),
      confidence: Number(Number(data.confidence ?? 0).toFixed(2)),
      recommendedSpare: data.recommended_spare || null,
      failureModes,
      source: 'azure openai',
      evidence: {},
    },
  },
}];

// Built-in diagnosis -- the no-cloud path.
//
// This is not a stub. It is a real rule-based diagnosis over the same retrieved
// manual sections the LLM branch would use, so the workflow produces sensible,
// citable output with no Azure account attached. That is what makes this
// importable-and-working rather than importable-and-needs-six-keys.

const cfg = $('Load config').first().json.config;
const { signal, guard, asset, assetConfidence, assetCandidates, citations } = $input.first().json;

const text = signal.text.toLowerCase();
const has = (s, markers) => markers.filter((m) => new RegExp(`\\b${m.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\b`, 'i').test(s));

// Phrases that, in a MANUAL, mean the equipment is dangerous right now.
const MANUAL_SAFETY = ['safety critical','unsafe to operate','must not be operated','taken out of service immediately','must be taken out of service','lock out','snap-back','lethal','statutory','drop under gravity','no lifting operation may continue','severe safety hazard','must not run'];
const MANUAL_ENV = ['oil release','release to water','spill','contaminates','fire risk'];

// What an operator writes, graded. First hit wins, most severe first.
const SIGNAL_SEVERITY = [
  ['critical', ['will not start','wont start',"won't start",'failed to start','seized','snapped','parted','fire','cracked','crack','total failure','load drifts','drifts down','drifting down','does not stop',"doesn't stop",'not stopping','unresponsive','collapsed','no longer works']],
  ['high',     ['leaking','leak','leaks','overheating','overheat','alarm','tripped','grinding','pressure loss','loss of pressure','torn','burning smell','sparking','out of tolerance','quality escape','smoke','black smoke']],
  ['medium',   ['noise','noisy','knocking','rattling','vibration','vibrating','juddering','weeping','seeping','intermittent','sluggish','warm','hot','deviation','occasionally']],
  ['low',      ['cosmetic','scratch','paint','label','minor','slight','monitoring','trending','routine','for information']],
];
const INJURY = ['injured','injury','hurt','burned','burnt','crushed','struck by','hit by','taken to hospital','first aid','laceration','fracture'];
const NEAR_MISS = ['near miss','near-miss','nearly hit','almost hit','close call'];
const ENV_SIGNAL = ['spill','spilled','into the water','overboard','on the ground','on the floor','reached the deck','contaminated'];

const RANK = { low: 0, medium: 1, high: 2, critical: 3 };
const worst = (a, b) => (RANK[a] >= RANK[b] ? a : b);

// Telemetry thresholds. In production these come from the asset's condition
// monitoring policy; here they are the manual's published limits.
const THRESHOLDS = [['vibration', 7.1, 11.0], ['temperature', 90, 98], ['temp', 90, 98]];

let severity = 'medium';
let evidence = [];
for (const [level, markers] of SIGNAL_SEVERITY) {
  const hits = has(text, markers);
  if (hits.length) { severity = level; evidence = hits; break; }
}

const readingHits = [];
for (const [key, value] of Object.entries(signal.readings ?? {})) {
  for (const [marker, high, critical] of THRESHOLDS) {
    if (!key.toLowerCase().includes(marker)) continue;
    if (value >= critical) { severity = worst(severity, 'critical'); readingHits.push(`${key}=${value} at or above the critical limit ${critical}`); }
    else if (value >= high) { severity = worst(severity, 'high'); readingHits.push(`${key}=${value} at or above the alert limit ${high}`); }
  }
}

// Hazard flags come from the section that describes THIS fault -- the top hit --
// plus anything effectively tied with it. Within a class-filtered corpus every
// section shares the class word, so a section about an unrelated fault on the
// same machine ("Conveyor Emergency Stop Integrity") scores high on overlap
// alone and would otherwise flag a routine bearing trend as safety-critical.
const evidenceCitations = citations.filter((c) => c.score >= 0.97);
const corpus = evidenceCitations.map((c) => `${c.heading} ${c.text}`).join(' ').toLowerCase();

const safetyRisk = has(corpus, MANUAL_SAFETY).length > 0;
if (safetyRisk) severity = worst(severity, 'high');

const injury = has(text, INJURY).length > 0;
const nearMiss = has(text, NEAR_MISS).length > 0;
if (injury) severity = 'critical';

const environmentalRisk =
  (has(corpus, MANUAL_ENV).length > 0 && has(text, ['leak','leaking','leakage','spill','oil','fuel','coolant','hydraulic','release']).length > 0)
  || has(text, ENV_SIGNAL).length > 0;

// Only sections that plausibly describe this fault become failure modes. A
// weakly matched section is a useful source but listing it as a "22% likely
// failure mode" is noise that trains people to skim.
const failureModes = citations.filter((c) => c.score >= 0.3).slice(0, 3).map((c) => ({
  name: c.heading,
  likelihood: c.score,
  rationale: c.text.split('. ')[0] + '.',
  citation: `${c.docId} ${c.section}`,
}));

let confidence = 0.35 + 0.35 * (citations[0]?.score ?? 0)
  + (evidence.length || readingHits.length ? 0.12 : 0)
  + (citations.length >= 2 ? 0.10 : 0);
if (!citations.length) confidence = 0.25;
confidence = Number(Math.min(confidence, 0.93).toFixed(2));

// Prefer a SKU the manual itself names; fall back to the class catalogue.
let spare = null;
for (const c of evidenceCitations.length ? evidenceCitations : citations.slice(0, 1)) {
  const m = c.text.match(/\b[A-Z]{3,4}-[A-Z0-9-]{2,}\b/);
  if (m && cfg.spares.some((s) => s.sku === m[0])) { spare = m[0]; break; }
}
if (!spare && asset) {
  const forClass = cfg.spares.filter((s) => s.classes.includes(asset.class));
  if (forClass.length === 1) spare = forClass[0].sku;
}

const lead = failureModes[0]?.name?.toLowerCase() ?? 'an unclassified fault';
const summary = `Most likely ${lead}, assessed as ${severity} severity`
  + (safetyRisk ? ' with a safety risk to personnel' : '')
  + (environmentalRisk ? ' and a potential environmental release' : '')
  + `. Grounded in ${citations.length} manual section(s); `
  + (readingHits.length ? 'telemetry exceeds published limits' : 'based on the reported symptoms') + '.';

return [{
  json: {
    signal, guard, asset, assetConfidence, assetCandidates, citations,
    diagnosis: {
      summary, severity, safetyRisk, environmentalRisk, injury, nearMiss,
      confidence, recommendedSpare: spare, failureModes,
      source: 'built-in rules',
      evidence: { signalMarkers: evidence, readingMarkers: readingHits },
    },
  },
}];

// Risk scoring, policy engine and action planning.
//
// This is the part that decides, and it is deliberately deterministic. The model
// (when configured) diagnoses and explains; what priority the work gets, whether
// a human must sign it off, and which actions are permitted are all decided
// here from the rules in data/config.json. You can unit-test this. You cannot
// unit-test a prompt's judgement.

const cfg = $('Load config').first().json.config;
const input = $input.first().json;
const { signal, guard, asset, assetConfidence, assetCandidates, citations, diagnosis } = input;

// ------------------------------------------------------------ risk scoring

// Published, boring, and the same answer every time -- which is exactly what a
// maintenance planner wants from an automated system.
const MATRIX = {
  critical: { 5: 'P1', 4: 'P1', 3: 'P2', 2: 'P2', 1: 'P2' },
  high:     { 5: 'P1', 4: 'P2', 3: 'P2', 2: 'P3', 1: 'P3' },
  medium:   { 5: 'P2', 4: 'P3', 3: 'P3', 2: 'P3', 1: 'P4' },
  low:      { 5: 'P3', 4: 'P4', 3: 'P4', 2: 'P4', 1: 'P4' },
};
const ORDER = { P1: 1, P2: 2, P3: 3, P4: 4 };

const criticality = asset?.criticality ?? 3;
let priority = MATRIX[diagnosis.severity]?.[criticality] ?? 'P3';
const reasons = [`severity=${diagnosis.severity} x criticality=${criticality} -> ${priority}`];

if (diagnosis.safetyRisk && ORDER[priority] > 1) { priority = 'P1'; reasons.push('safety risk to personnel escalates to P1'); }
if (diagnosis.injury) { priority = 'P1'; reasons.push('injury reported escalates to P1'); }
if (diagnosis.environmentalRisk && ORDER[priority] > 2) { priority = 'P2'; reasons.push('environmental release risk escalates to at least P2'); }

// ------------------------------------------------------------ policy engine

const spare = diagnosis.recommendedSpare ? cfg.spares.find((s) => s.sku === diagnosis.recommendedSpare) : null;

const ctx = {
  resolved: Boolean(asset),
  criticality,
  severity: diagnosis.severity,
  safetyRisk: diagnosis.safetyRisk,
  environmentalRisk: diagnosis.environmentalRisk,
  injury: diagnosis.injury,
  nearMiss: diagnosis.nearMiss,
  confidence: diagnosis.confidence,
  citationCount: citations.length,
  isLifting: asset ? ['crane', 'winch'].includes(asset.class) : false,
  spareSku: spare?.sku ?? null,
  spareInStock: spare ? spare.stock > 0 : false,
  spareLeadTimeDays: spare?.leadTimeDays ?? 0,
};

// Rule expressions live in config, so they get a character allow-list before
// evaluation: identifiers, numbers, quoted strings and comparison/boolean
// operators only. No property access, brackets, calls or arrows -- which rules
// out property-chain escapes (`x.constructor.constructor`) by construction
// rather than by blacklist.
//
// Number literals are blanked before the check, because a decimal point is a
// dot and `confidence < 0.55` is a perfectly ordinary rule.
const SAFE_EXPR = /^[A-Za-z0-9_\s'"=!<>&|()+\-*/.]*$/;
const BANNED = /(\.|=>|\[|\]|`|;|\bthis\b|\bfunction\b|\bnew\b|\bimport\b|\brequire\b|\bglobalThis\b|\bprocess\b|\bconstructor\b)/;
const withoutNumbers = (expr) => expr.replace(/\d+(?:\.\d+)?/g, '0');

const keys = Object.keys(ctx);
const values = keys.map((k) => ctx[k]);
const findings = [];
const badRules = [];

for (const rule of cfg.rules) {
  const expr = String(rule.when);
  if (!SAFE_EXPR.test(expr) || BANNED.test(withoutNumbers(expr))) { badRules.push(rule.id); continue; }
  let fired = false;
  try {
    fired = Boolean(new Function(...keys, `"use strict"; return (${expr});`)(...values));
  } catch (e) {
    badRules.push(rule.id);
    continue;
  }
  if (!fired) continue;
  findings.push({
    ruleId: rule.id,
    severity: rule.severity,
    priority: rule.priority,
    message: String(rule.message).replace(/\{(\w+)\}/g, (_, k) => (ctx[k] ?? 'n/a')),
    actions: rule.actions ?? [],
    citation: rule.citation,
  });
}

// A rule we could not evaluate might have been the one that would have stopped
// us. Fail closed rather than pretend a clean pass.
if (badRules.length) {
  throw new Error(`Policy rules could not be evaluated: ${badRules.join(', ')}. Refusing to continue.`);
}

findings.sort((a, b) => ORDER[a.priority] - ORDER[b.priority]);
if (findings.length && ORDER[findings[0].priority] < ORDER[priority]) {
  priority = findings[0].priority;
  reasons.push(`policy rule ${findings[0].ruleId} raises it to ${priority}`);
}

// ------------------------------------------------------------ action plan

const allowed = Object.fromEntries(cfg.allowedActions.map((a) => [a.id, a]));
const actions = [];
for (const finding of findings) {
  for (const id of finding.actions) {
    // The allow-list is a ceiling, not a suggestion.
    if (!allowed[id] || actions.some((a) => a.id === id)) continue;
    actions.push({
      id,
      label: allowed[id].label,
      reversible: allowed[id].reversible,
      rationale: `${finding.message} (${finding.citation})`,
      sourceRules: findings.filter((f) => f.actions.includes(id)).map((f) => f.ruleId),
    });
  }
}
if (!actions.length) {
  // A silent no-op is the worst outcome: nobody knows nothing happened.
  actions.push({
    id: 'require_human_review',
    label: allowed.require_human_review.label,
    reversible: true,
    rationale: 'No policy rule covered this case; routing to a human so the gap is visible.',
    sourceRules: [],
  });
}

// ------------------------------------------------------- the approval gate

const approvalReasons = [];
if (ORDER[priority] <= ORDER[cfg.policy.humanApprovalAtOrAbove]) approvalReasons.push(`priority ${priority} is at or above the ${cfg.policy.humanApprovalAtOrAbove} approval threshold`);
if (diagnosis.confidence < cfg.policy.confidenceFloor) approvalReasons.push(`confidence ${diagnosis.confidence} is below the ${cfg.policy.confidenceFloor} floor`);
if (!asset) approvalReasons.push('the asset could not be identified');
if (findings.some((f) => f.severity === 'blocker')) approvalReasons.push('a blocker-severity policy rule fired');
const irreversible = actions.filter((a) => !a.reversible).map((a) => a.id);
if (irreversible.length) approvalReasons.push(`the plan contains irreversible action(s): ${irreversible.join(', ')}`);

const slaHours = cfg.policy.slaHours[priority] ?? 168;

return [{
  json: {
    runId: signal.runId,
    receivedAt: signal.receivedAt,
    status: approvalReasons.length ? 'awaiting_approval' : 'auto_dispatch',
    requiresApproval: approvalReasons.length > 0,
    approvalReason: approvalReasons.join('; '),
    priority,
    priorityReasons: reasons,
    slaDueAt: new Date(Date.now() + slaHours * 3600 * 1000).toISOString(),
    asset: asset ? { id: asset.id, name: asset.name, site: asset.site, criticality: asset.criticality, class: asset.class } : null,
    assetConfidence,
    assetCandidates,
    diagnosis,
    findings,
    actions,
    citations: citations.map((c) => ({ docId: c.docId, section: c.section, heading: c.heading, score: c.score })),
    redactions: signal.redactions,
    reportedText: signal.text,
  },
}];
